mapper.select:
select *
  from (
        select a.*, rownum rn
          from (
                select q.qna_seq, q.member_seq, q.title, q.is_secret,
                       q.answer_status, q.created_at, q.updated_at,
                       m.nickname as writer_name
                  from qna q
                  left join member m on m.member_seq = q.member_seq
                 where q.is_deleted = 'N'

                   and q.member_seq = #{memberSeq}

                 order by q.qna_seq desc
               ) a
         where rownum <= #{endRow}
       )
 where rn > #{startRow}
